/** 自己加的原因行必须填类型和原因，否则存下来的就是一行空白 */
validateFloodPayload(payload) {
  const base = floodDetailPage.methods.validateFloodPayload.call(this, payload)
  if (base) return base
  const invalid = (this.form.items || []).find((i) => this.isCustomCause(i)
    && (!String(i.causeType || '').trim() || !String(i.causeReference || '').trim()))
  return invalid ? '新增的原因需要填写类型和原因' : ''
},

tool_input.new_string:
/**
 * 自己加的原因行必须填类型和原因；
 * 模板行与自定义行都要求填写复盘内容（积水原因复盘必填，见禅道 bug6402）。
 */
validateFloodPayload(payload) {
  const base = floodDetailPage.methods.validateFloodPayload.call(this, payload)
  if (base) return base
  const items = this.form.items || []
  const customInvalid = items.find((i) => this.isCustomCause(i)
    && (!String(i.causeType || '').trim() || !String(i.causeReference || '').trim()))
  if (customInvalid) return '新增的原因需要填写类型和原因'
  const reviewIndex = items.findIndex((i) => !String(i.reviewContent || '').trim())
  if (reviewIndex > -1) return `请填写第${reviewIndex + 1}条积水原因复盘内容`
  return ''
},

